1	/**
2	 * Sheaf Chat browser UI: piles, sessions, and interactive chat screens.
3	 */
4	(function () {
5	  "use strict";
6	
7	  const x_ClientIdKey = "sheaf-chat-client-id";
8	  const x_DefaultRootDirectory = "projects";
9	  const x_HistoryPageLimit = 50;
10	  const x_InitialHistoryLimit = 80;
11	  const x_ReconnectDelayMs = 1500;
12	
13	  function CreateElement(tag, className) {
14	    const element = document.createElement(tag);
15	    if (className) {
16	      element.className = className;
17	    }
18	    return element;
19	  }
20	
21	  function GenerateId() {
22	    if (typeof crypto !== "undefined" && crypto.randomUUID) {
23	      return crypto.randomUUID();
24	    }
25	    return "id-" + Date.now() + "-" + Math.random().toString(16).slice(2);
26	  }
27	
28	  function GetClientId() {
29	    try {
30	      const existing = localStorage.getItem(x_ClientIdKey);
31	      if (existing) {
32	        return existing;
33	      }
34	      const created = GenerateId();
35	      localStorage.setItem(x_ClientIdKey, created);
36	      return created;
37	    } catch (_error) {
38	      return GenerateId();
39	    }
40	  }
41	
42	  function IsTouchLayout() {
43	    if (typeof window === "undefined") {
44	      return false;
45	    }
46	    if (window.matchMedia && window.matchMedia("(pointer: coarse)").matches) {
47	      return true;
48	    }
49	    return "ontouchstart" in window;
50	  }
51	
52	  function ParseRoute() {
53	    const hash = (window.location.hash || "#/").replace(/^#/, "");
54	    const parts = hash.split("/").filter(function (part) {
55	      return part.length > 0;
56	    });
57	
58	    if (parts.length === 0) {
59	      return { screen: "piles" };
60	    }
61	
62	    if (parts[0] === "piles" && parts.length === 1) {
63	      return { screen: "piles" };
64	    }
65	
66	    if (parts[0] === "piles" && parts.length === 2) {
67	      return { screen: "sessions", pile: decodeURIComponent(parts[1]) };
68	    }
69	
70	    if (
71	      parts[0] === "piles" &&
72	      parts.length === 4 &&
73	      parts[2] === "sessions"
74	    ) {
75	      return {
76	        screen: "chat",
77	        pile: decodeURIComponent(parts[1]),
78	        sessionId: decodeURIComponent(parts[3]),
79	      };
80	    }
81	
82	    return { screen: "piles" };
83	  }
84	
85	  function NavigateTo(route) {
86	    if (route.screen === "piles") {
87	      window.location.hash = "#/";
88	      return;
89	    }
90	
91	    if (route.screen === "sessions") {
92	      window.location.hash = "#/piles/" + encodeURIComponent(route.pile);
93	      return;
94	    }
95	
96	    if (route.screen === "chat") {
97	      window.location.hash =
98	        "#/piles/" +
99	        encodeURIComponent(route.pile) +
100	        "/sessions/" +
101	        encodeURIComponent(route.sessionId);
102	    }
103	  }
104	
105	  async function FetchJson(path, options) {
106	    const response = await fetch(path, options);
107	    const body = await response.json();
108	    if (!response.ok) {
109	      const message =
110	        body &&
111	        body.error &&
112	        body.error.message != null
113	          ? String(body.error.message)
114	          : "request failed";
115	      throw new Error(message);
116	    }
117	    return body;
118	  }
119	
120	  function FormatTimestamp(value) {
121	    if (!value) {
122	      return "";
123	    }
124	    try {
125	      return new Date(value).toLocaleString();
126	    } catch (_error) {
127	      return String(value);
128	    }
129	  }
130	
131	  function CreateScreenShell(title, onBack) {
132	    const screen = CreateElement("div", "sheaf-chat-screen");
133	    const header = CreateElement("header", "sheaf-chat-header");
134	
135	    if (onBack) {
136	      const back = CreateElement("button", "sheaf-chat-back");
137	      back.type = "button";
138	      back.textContent = "Back";
139	      back.addEventListener("click", onBack);
140	      header.appendChild(back);
141	    }
142	
143	    const heading = CreateElement("h1", "sheaf-chat-header-title");
144	    heading.textContent = title;
145	    header.appendChild(heading);
146	    screen.appendChild(header);
147	
148	    const content = CreateElement("div", "sheaf-chat-content");
149	    screen.appendChild(content);
150	
151	    return { screen, content };
152	  }
153	
154	  function RenderPilesScreen(app, route) {
155	    app.textContent = "";
156	    const shell = CreateScreenShell("Piles", null);
157	    app.appendChild(shell.screen);
158	
159	    const list = CreateElement("ul", "sheaf-chat-list");
160	    shell.content.appendChild(list);
161	
162	    const errorNode = CreateElement("div", "sheaf-chat-error");
163	    shell.content.appendChild(errorNode);
164	
165	    const form = CreateElement("form", "sheaf-chat-form");
166	    const field = CreateElement("div", "sheaf-chat-field");
167	    const label = CreateElement("label", "sheaf-chat-label");
168	    label.textContent = "New pile name";
169	    label.htmlFor = "sheaf-chat-new-pile";
170	    const input = CreateElement("input", "sheaf-chat-input");
171	    input.id = "sheaf-chat-new-pile";
172	    input.name = "pile";
173	    input.required = true;
174	    input.autocomplete = "off";
175	    field.appendChild(label);
176	    field.appendChild(input);
177	    form.appendChild(field);
178	
179	    const submit = CreateElement("button", "sheaf-chat-button sheaf-chat-button--primary");
180	    submit.type = "submit";
181	    submit.textContent = "Create pile";
182	    form.appendChild(submit);
183	    shell.screen.appendChild(form);
184	
185	    function RenderPileRows(piles) {
186	      list.textContent = "";
187	      errorNode.textContent = "";
188	
189	      if (!piles || piles.length === 0) {
190	        const empty = CreateElement("p", "sheaf-chat-empty");
191	        empty.textContent = "No piles yet. Create one below.";
192	        list.appendChild(empty);
193	        return;
194	      }
195	
196	      for (const pile of piles) {
197	        const item = CreateElement("li", "sheaf-chat-list-item");
198	        const button = CreateElement("button", "sheaf-chat-list-button");
199	        button.type = "button";
200	        button.textContent = pile.name;
201	        const meta = CreateElement("span", "sheaf-chat-list-meta");
202	        meta.textContent =
203	          (pile.sessionCount != null ? pile.sessionCount : 0) +
204	          " sessions" +
205	          (pile.updatedAt ? " · " + FormatTimestamp(pile.updatedAt) : "");
206	        button.appendChild(meta);
207	        button.addEventListener("click", function () {
208	          NavigateTo({ screen: "sessions", pile: pile.name });
209	        });
210	        item.appendChild(button);
211	        list.appendChild(item);
212	      }
213	    }
214	
215	    form.addEventListener("submit", function (event) {
216	      event.preventDefault();
217	      errorNode.textContent = "";
218	      const pileName = input.value.trim();
219	      if (!pileName) {
220	        return;
221	      }
222	
223	      submit.disabled = true;
224	      FetchJson("/api/piles", {
225	        method: "POST",
226	        headers: { "content-type": "application/json" },
227	        body: JSON.stringify({ pile: pileName }),
228	      })
229	        .then(function () {
230	          input.value = "";
231	          return FetchJson("/api/piles");
232	        })
233	        .then(function (body) {
234	          RenderPileRows(body.piles || []);
235	        })
236	        .catch(function (error) {
237	          errorNode.textContent = error.message || "Failed to create pile";
238	        })
239	        .finally(function () {
240	          submit.disabled = false;
241	        });
242	    });
243	
244	    FetchJson("/api/piles")
245	      .then(function (body) {
246	        RenderPileRows(body.piles || []);
247	      })
248	      .catch(function (error) {
249	        errorNode.textContent = error.message || "Failed to load piles";
250	      });
251	  }
252	
253	  function RenderSessionsScreen(app, route) {
254	    app.textContent = "";
255	    const shell = CreateScreenShell(route.pile, function () {
256	      NavigateTo({ screen: "piles" });
257	    });
258	    app.appendChild(shell.screen);
259	
260	    const list = CreateElement("ul", "sheaf-chat-list");
261	    shell.content.appendChild(list);
262	    const errorNode = CreateElement("div", "sheaf-chat-error");
263	    shell.content.appendChild(errorNode);
264	
265	    const form = CreateElement("form", "sheaf-chat-form");
266	    const rootField = CreateElement("div", "sheaf-chat-field");
267	    const rootLabel = CreateElement("label", "sheaf-chat-label");
268	    rootLabel.textContent = "Root directory";
269	    rootLabel.htmlFor = "sheaf-chat-root-directory";
270	    const rootInput = CreateElement("input", "sheaf-chat-input");
271	    rootInput.id = "sheaf-chat-root-directory";
272	    rootInput.name = "rootDirectory";
273	    rootInput.required = true;
274	    rootInput.value = x_DefaultRootDirectory;
275	    rootField.appendChild(rootLabel);
276	    rootField.appendChild(rootInput);
277	
278	    const modelField = CreateElement("div", "sheaf-chat-field");
279	    const modelLabel = CreateElement("label", "sheaf-chat-label");
280	    modelLabel.textContent = "Model";
281	    modelLabel.htmlFor = "sheaf-chat-new-session-model";
282	    const modelSelect = CreateElement("select", "sheaf-chat-select");
283	    modelSelect.id = "sheaf-chat-new-session-model";
284	    modelSelect.name = "model";
285	    modelSelect.required = true;
286	    modelField.appendChild(modelLabel);
287	    modelField.appendChild(modelSelect);
288	
289	    form.appendChild(rootField);
290	    form.appendChild(modelField);
291	
292	    const submit = CreateElement("button", "sheaf-chat-button sheaf-chat-button--primary");
293	    submit.type = "submit";
294	    submit.textContent = "New session";
295	    form.appendChild(submit);
296	    shell.screen.appendChild(form);
297	
298	    let models = [];
299	
300	    function RenderSessionRows(sessions) {
301	      list.textContent = "";
302	      if (!sessions || sessions.length === 0) {
303	        const empty = CreateElement("p", "sheaf-chat-empty");
304	        empty.textContent = "No sessions in this pile yet.";
305	        list.appendChild(empty);
306	        return;
307	      }
308	
309	      for (const session of sessions) {
310	        const item = CreateElement("li", "sheaf-chat-list-item");
311	        const button = CreateElement("button", "sheaf-chat-list-button");
312	        button.type = "button";
313	        const title =
314	          session.chatName ||
315	          session.description ||
316	          session.sessionId ||
317	          "Session";
318	        button.textContent = title;
319	        const meta = CreateElement("span", "sheaf-chat-list-meta");
320	        const model =
321	          session.model && session.model.id
322	            ? session.model.provider + "/" + session.model.id
323	            : "";
324	        meta.textContent =
325	          (session.rootDirectory || "") +
326	          (model ? " · " + model : "") +
327	          (session.updatedAt ? " · " + FormatTimestamp(session.updatedAt) : "");
328	        button.appendChild(meta);
329	        button.addEventListener("click", function () {
330	          NavigateTo({
331	            screen: "chat",
332	            pile: route.pile,
333	            sessionId: session.sessionId,
334	          });
335	        });
336	        item.appendChild(button);
337	        list.appendChild(item);
338	      }
339	    }
340	
341	    function PopulateModelSelect() {
342	      modelSelect.textContent = "";
343	      for (const model of models) {
344	        const option = document.createElement("option");
345	        option.value = model.provider + ":" + model.id;
346	        option.textContent =
347	          (model.displayName || model.id) +
348	          (model.available === false ? " (unavailable)" : "");
349	        option.disabled = model.available === false;
350	        modelSelect.appendChild(option);
351	      }
352	    }
353	
354	    form.addEventListener("submit", function (event) {
355	      event.preventDefault();
356	      errorNode.textContent = "";
357	      const selected = modelSelect.value.split(":");
358	      if (selected.length !== 2) {
359	        errorNode.textContent = "Select a model";
360	        return;
361	      }
362	
363	      submit.disabled = true;
364	      FetchJson("/api/piles/" + encodeURIComponent(route.pile) + "/sessions", {
365	        method: "POST",
366	        headers: { "content-type": "application/json" },
367	        body: JSON.stringify({
368	          rootDirectory: rootInput.value.trim(),
369	          model: { provider: selected[0], id: selected[1] },
370	        }),
371	      })
372	        .then(function (body) {
373	          NavigateTo({
374	            screen: "chat",
375	            pile: route.pile,
376	            sessionId: body.sessionId,
377	          });
378	        })
379	        .catch(function (error) {
380	          errorNode.textContent = error.message || "Failed to create session";
381	        })
382	        .finally(function () {
383	          submit.disabled = false;
384	        });
385	    });
386	
387	    Promise.all([
388	      FetchJson("/api/models"),
389	      FetchJson("/api/piles/" + encodeURIComponent(route.pile) + "/sessions"),
390	    ])
391	      .then(function (results) {
392	        models = results[0].models || [];
393	        PopulateModelSelect();
394	        RenderSessionRows(results[1].sessions || []);
395	      })
396	      .catch(function (error) {
397	        errorNode.textContent = error.message || "Failed to load sessions";
398	      });
399	  }
400	
401	  function BuildWebSocketUrl(pile, sessionId, after) {
402	    const params = new URLSearchParams();
403	    params.set("p", pile);
404	    params.set("session", sessionId);
405	    params.set("client", GetClientId());
406	    if (after != null && after > 0) {
407	      params.set("after", String(after));
408	    }
409	
410	    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
411	    return (
412	      protocol +
413	      "//" +
414	      window.location.host +
415	      "/ws/chat?" +
416	      params.toString()
417	    );
418	  }
419	
420	  function CreateEnvelope(kind, pile, sessionId, payload) {
421	    return {
422	      v: 1,
423	      kind: kind,
424	      id: GenerateId(),
425	      pile: pile,
426	      sessionId: sessionId,
427	      timestamp: new Date().toISOString(),
428	      payload: payload,
429	    };
430	  }
431	
432	  function RenderChatScreen(app, route) {
433	    app.textContent = "";
434	    if (!window.ChatView) {
435	      const missing = CreateElement("p", "sheaf-chat-error");
436	      missing.textContent = "Chat renderer failed to load.";
437	      app.appendChild(missing);
438	      return;
439	    }
440	
441	    const touchLayout = IsTouchLayout();
442	    app.classList.toggle("sheaf-chat-touch", touchLayout);
443	    app.classList.toggle("sheaf-chat-desktop", !touchLayout);
444	
445	    const screen = CreateElement("div", "sheaf-chat-screen sheaf-chat-chat-layout");
446	    const header = CreateElement("header", "sheaf-chat-header");
447	    const back = CreateElement("button", "sheaf-chat-back");
448	    back.type = "button";
449	    back.textContent = "Back";
450	    back.addEventListener("click", function () {
451	      NavigateTo({ screen: "sessions", pile: route.pile });
452	    });
453	    header.appendChild(back);
454	
455	    const title = CreateElement("h1", "sheaf-chat-header-title");
456	    title.textContent = route.sessionId;
457	    header.appendChild(title);
458	    screen.appendChild(header);
459	
460	    const statusRow = CreateElement("div", "sheaf-chat-chat-status");
461	    const connectionLabel = CreateElement("span");
462	    connectionLabel.textContent = "Connecting…";
463	    statusRow.appendChild(connectionLabel);
464	
465	    const modelSelect = CreateElement("select", "sheaf-chat-model-select");
466	    statusRow.appendChild(modelSelect);
467	    screen.appendChild(statusRow);
468	
469	    const chatMain = CreateElement("div", "sheaf-chat-chat-main");
470	    const chatContainer = CreateElement("div");
471	    chatMain.appendChild(chatContainer);
472	    screen.appendChild(chatMain);
473	
474	    const composer = CreateElement("div", "sheaf-chat-composer");
475	    const textarea = CreateElement("textarea", "sheaf-chat-textarea");
476	    textarea.rows = 1;
477	    textarea.placeholder = "Message the agent…";
478	    const sendButton = CreateElement(
479	      "button",
480	      "sheaf-chat-button sheaf-chat-button--primary sheaf-chat-send"
481	    );
482	    sendButton.type = "button";
483	    sendButton.textContent = "Send";
484	    composer.appendChild(textarea);
485	    composer.appendChild(sendButton);
486	    screen.appendChild(composer);
487	    app.appendChild(screen);
488	
489	    let socket = null;
490	    let chatHandle = null;
491	    let destroyed = false;
492	    let connected = false;
493	    let lastSequence = 0;
494	    let oldestSequence = null;
495	    let hasMoreBefore = false;
496	    let historyLoading = false;
497	    let models = [];
498	    let activeModel = null;
499	    let reconnectTimer = null;
500	    let intentionalClose = false;
501	    const outboundQueue = [];
502	
503	    function UpdateComposerState() {
504	      const queuedCount = outboundQueue.length;
505	      composer.classList.toggle("sheaf-chat-composer--disconnected", !connected);
506	      composer.classList.toggle("sheaf-chat-composer--queued", queuedCount > 0);
507	      textarea.disabled = false;
508	      sendButton.disabled = !connected && queuedCount === 0;
509	      if (chatHandle) {
510	        window.ChatView.setConnectionState(chatHandle, {
511	          connected: connected,
512	          queuedCount: queuedCount,
513	          label: connected ? null : "Disconnected",
514	        });
515	      }
516	    }
517	
518	    function ResizeTextarea() {
519	      textarea.style.height = "auto";
520	      const maxHeight = 200;
521	      textarea.style.height =
522	        Math.min(textarea.scrollHeight, maxHeight) + "px";
523	    }
524	
525	    function PopulateModels() {
526	      modelSelect.textContent = "";
527	      for (const model of models) {
528	        const option = document.createElement("option");
529	        option.value = model.provider + ":" + model.id;
530	        const selected =
531	          activeModel &&
532	          activeModel.provider === model.provider &&
533	          activeModel.id === model.id;
534	        option.selected = selected;
535	        option.textContent =
536	          (model.displayName || model.id) +
537	          (model.available === false ? " (unavailable)" : "");
538	        option.disabled = model.available === false;
539	        modelSelect.appendChild(option);
540	      }
541	    }
542	
543	    function UpdateStatusText() {
544	      const modelText =
545	        activeModel != null
546	          ? activeModel.provider + "/" + activeModel.id
547	          : "model unknown";
548	      connectionLabel.innerHTML =
549	        "<strong>" +
550	        (connected ? "Connected" : "Disconnected") +
551	        "</strong> · " +
552	        modelText;
553	    }
554	
555	    function SendEnvelope(envelope) {
556	      if (!socket || socket.readyState !== WebSocket.OPEN) {
557	        return false;
558	      }
559	      socket.send(JSON.stringify(envelope));
560	      return true;
561	    }
562	
563	    function FlushQueue() {
564	      if (!connected) {
565	        return;
566	      }
567	      while (outboundQueue.length > 0) {
568	        const item = outboundQueue[0];
569	        if (!SendEnvelope(item)) {
570	          break;
571	        }
572	        outboundQueue.shift();
573	      }
574	      UpdateComposerState();
575	    }
576	
577	    function QueueOrSend(envelope) {
578	      if (SendEnvelope(envelope)) {
579	        return;
580	      }
581	      outboundQueue.push(envelope);
582	      UpdateComposerState();
583	    }
584	
585	    function SendAck(sequence) {
586	      if (sequence == null || sequence <= 0) {
587	        return;
588	      }
589	      SendEnvelope(
590	        CreateEnvelope("client.ack", route.pile, route.sessionId, {
591	          sequence: sequence,
592	        })
593	      );
594	    }
595	
596	    function RequestHistory(options) {
597	      const payload = {
598	        limit: options.limit || x_HistoryPageLimit,
599	        prefer: "snapshots",
600	      };
601	      if (options.before != null) {
602	        payload.before = options.before;
603	      }
604	      if (options.after != null) {
605	        payload.after = options.after;
606	      }
607	      const envelope = CreateEnvelope(
608	        "client.history_request",
609	        route.pile,
610	        route.sessionId,
611	        payload
612	      );
613	      if (options.before != null) {
614	        historyLoading = true;
615	      }
616	      QueueOrSend(envelope);
617	    }
618	
619	    function HandleHistoryPage(payload) {
620	      historyLoading = false;
621	      if (!payload) {
622	        return;
623	      }
624	
625	      if (payload.oldestSequence != null) {
626	        oldestSequence = payload.oldestSequence;
627	      }
628	      if (payload.hasMoreBefore != null) {
629	        hasMoreBefore = payload.hasMoreBefore === true;
630	      }
631	
632	      const messages = Array.isArray(payload.messages) ? payload.messages : [];
633	      if (messages.length > 0 && chatHandle) {
634	        window.ChatView.prependHistory(chatHandle, messages);
635	      }
636	
637	      const events = Array.isArray(payload.events) ? payload.events : [];
638	      for (const event of events) {
639	        if (event && chatHandle) {
640	          window.ChatView.appendAguiEvent(chatHandle, event);
641	        }
642	      }
643	    }
644	
645	    function HandleServerEnvelope(envelope) {
646	      if (!envelope || typeof envelope !== "object") {
647	        return;
648	      }
649	
650	      if (envelope.sequence != null && envelope.sequence > lastSequence) {
651	        lastSequence = envelope.sequence;
652	        SendAck(envelope.sequence);
653	      }
654	
655	      const kind = envelope.kind;
656	      const payload = envelope.payload;
657	
658	      if (kind === "server.hello") {
659	        if (payload && Array.isArray(payload.models)) {
660	          models = payload.models;
661	        }
662	        if (payload && payload.activeModel) {
663	          activeModel = payload.activeModel;
664	        }
665	        if (payload && payload.manifest && payload.manifest.chatName) {
666	          title.textContent = payload.manifest.chatName;
667	        }
668	        if (payload && payload.latestSequence != null) {
669	          lastSequence = Math.max(lastSequence, payload.latestSequence);
670	        }
671	        if (payload && payload.historyWindow) {
672	          oldestSequence = payload.historyWindow.oldestSequence;
673	          hasMoreBefore =
674	            payload.historyWindow.oldestSequence != null &&
675	            payload.historyWindow.oldestSequence > 1;
676	        }
677	        PopulateModels();
678	        UpdateStatusText();
679	        RequestHistory({ limit: x_InitialHistoryLimit });
680	        return;
681	      }
682	
683	      if (kind === "history.page") {
684	        HandleHistoryPage(payload);
685	        return;
686	      }
687	
688	      if (kind === "agui.event" && payload) {
689	        if (chatHandle) {
690	          window.ChatView.appendAguiEvent(chatHandle, payload);
691	        }
692	        return;
693	      }
694	
695	      if (kind === "chat.user_message" && payload) {
696	        const messageId = payload.messageId || GenerateId();
697	        if (chatHandle) {
698	          window.ChatView.appendAguiEvent(chatHandle, {
699	            type: "TEXT_MESSAGE_START",
